def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def recoverSwappedValues(tree):
    val, left, right = parse(tree)
    first = second = None
    prev = None
    stack = []
    u = 0
    while stack or u != -1:
        while u != -1:
            stack.append(u)
            u = left[u]
        u = stack.pop()
        if prev is not None and prev > val[u]:
            if first is None:
                first = prev
            second = val[u]
        prev = val[u]
        u = right[u]
    return sorted([first, second])
